package academic

import (
	"strings"
)

// User messages already contain the submitted AskCard's readable answers. Keep
// their order; neither the card metadata nor a model's rewrite is a user input.
func paperUserInstruction(original string, updates []string) string {
	original = strings.TrimSpace(original)
	parts := []string{}
	if original != "" {
		parts = append(parts, original)
	}
	for i, update := range updates {
		text := strings.TrimSpace(update)
		if text == "" {
			continue
		}
		// The first message is generated by LaunchPaperWorkflow from the original
		// requirement. Include that requirement once, without its launch template.
		if i == 0 && (text == "请按照已确认范围执行四步论文拓展。准备成果已保存，请先读取任务上下文。" || text == original ||
			text == "请围绕所选论文或方向开展论文拓展。\n"+original ||
			text == "请先拓展论文，达到全文要求后在新的 Chat 生成综述。\n"+original) {
			continue
		}
		parts = append(parts, text)
	}
	return strings.Join(parts, "\n\n")
}
